from semantic_math import equation as scalar_markup

def step(title, equation, why):
    return dict(title=title, equation=scalar_markup(equation), why=why)

def node(n, concepts, anchor, intuition, steps, prerequisites, application, experiment, trap):
    return dict(chapterId=n, coreConcepts=concepts, anchor=anchor, intuition=intuition,
                derivation=steps, prerequisites=prerequisites, application=application,
                experiment=experiment, examTrap=trap,
                keyFormulas=[s['equation'] for s in steps])

