MID_SLIDES = ['set1_Vector1_for_prnt.pdf','set2_Vector2_for_prnt.pdf','set3_Vector3_for_prnt.pdf','set4_Coulomb_for_prnt.pdf','set5_E_field_for_prnt.pdf','set6_Flux_for_prnt.pdf','set7_Gauss_for_prnt.pdf','set8_Divergence_for_prnt.pdf','set9_Potential_for_prnt.pdf']
MID_SLUGS = ['01-vector-algebra','02-cylindrical-coordinates','03-spherical-coordinates','04-coulombs-law','05-electric-field-intensity','06-electric-flux-density','07-gauss-law','08-divergence-theorem','09-electric-potential']
MID_TITLES = ['พีชคณิตเวกเตอร์','พิกัดทรงกระบอก','พิกัดทรงกลม','กฎคูลอมบ์','ความเข้มสนามไฟฟ้า','ความหนาแน่นฟลักซ์ไฟฟ้า','กฎของเกาส์','ไดเวอร์เจนซ์','ศักย์ไฟฟ้า']
for c in NODES:
    n=c['chapterId']
    c['title']=MID_TITLES[n-1] if n<10 else next(x[2] for x in CHAPTERS if x[0]==n)
    c['slug']=MID_SLUGS[n-1] if n<10 else next(x[1] for x in CHAPTERS if x[0]==n)
    c['semester']='midterm' if n<10 else 'final'
    c['forwardLinks']=[dict(chapterId=k,reason=NODES[k-1]['anchor']) for k in range(n+1,23) if n in NODES[k-1]['prerequisites']]
    c['sources']=[dict(label='Set '+str(n)+' · สไลด์หลัก',path='lecture/'+(MID_SLIDES[n-1] if n<10 else 'final/'+next(x[5] for x in CHAPTERS if x[0]==n)),page=1)]


from masterclass_depth import DEPTH
for c in NODES:
    depth=DEPTH[c['chapterId']]
    c.update({k:v for k,v in depth.items() if k!='derivation'})
    c['derivation']=[step(*s) for s in depth['derivation']]
    c['coreBreakthrough']=' · '.join(c['coreConcepts'])
    c['formulasMastered']=c['keyFormulas']
    c['keyFormulas']=c['formulasMastered']
    c['forwardLink']=('แนวคิดของบทนี้เป็นฐานให้ '+', '.join('Set '+str(f['chapterId']) for f in c['forwardLinks']) if c['forwardLinks'] else 'นำสนามและเฟสไปต่อยอดสู่สายส่ง เสาอากาศ และการถ่ายโอนพลังงาน')
